#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


# Switches pinch-app.io/app from the Expo web app to the new web app (PIN-147), checks it, practises switching
# back once, and announces the new look. Run it from the repo root at a quiet hour, in Git Bash:
#   bash scripts/web-app-switch-wizard.sh
# From PowerShell, plain `bash` is WSL's; use Git Bash's instead:
#   & "C:\Program Files\Gitinash.exe" scripts/web-app-switch-wizard.sh
# The steps and the reasons behind them: docs/WEB-APP-SWITCH.md.

BRANCH="yardenfarag/pin-147-switch-pinch-appioapp-to-the-new-web-app"
CF_ROUTES_URL="https://dash.cloudflare.com/?to=/:account/workers/services/view/pinch-web/production/settings"
SUPABASE_URL_CONFIG="https://supabase.com/dashboard/project/ccobefeofhnncpgifxel/auth/url-configuration"

# gh may not be logged in on this machine; the git credential works too.
gh_ready() {
  gh auth status >/dev/null 2>&1 && return 0
  if [[ -z "${GH_TOKEN:-}" ]]; then
    GH_TOKEN=$(printf 'protocol=https\nhost=github.com\n\n' | git credential fill 2>/dev/null | sed -n 's/^password=//p')
    export GH_TOKEN
  fi
  gh api user >/dev/null 2>&1
}

# check_routing next|expo runs the routing check, retrying for a minute while Cloudflare catches up.
check_routing() {
  local i
  for i in 1 2 3 4 5 6; do
    if node scripts/check-web-routing.mjs --expect "$1"; then return 0; fi
    note "Trying again in 10 seconds…"
    sleep 10
  done
  return 1
}

# watch_run_since WORKFLOW SINCE waits for the first run of a workflow on master created at or after SINCE
# (UTC, as from `date -u +%Y-%m-%dT%H:%M:%SZ`), then follows it to the end.
watch_run_since() {
  local id="" i
  for i in $(seq 1 24); do
    id=$(gh run list --workflow "$1" --branch master --limit 5 --json databaseId,createdAt       -q "[.[] | select(.createdAt >= \"$2\")] | last | .databaseId // empty")
    [[ -n "$id" ]] && break
    sleep 5
  done
  if [[ -z "$id" ]]; then
    warn "No run of $1 started in the last two minutes. Check the Actions tab."
    return 1
  fi
  gh run watch "$id" --exit-status
}

run_wizard() {

TOTAL_STAGES=11

banner "Switch pinch-app.io/app to the new web app (PIN-147)"

# ──────────────────────────────────────────────────────────────────────────
stage "Before you start"
say "Do this at a quiet hour. It takes about an hour, most of it checking."
gh_ready || { warn "gh can't reach GitHub. Log in with 'gh auth login' and run this again."; exit 1; }
sales=$(gh variable get EXPO_PUBLIC_CREDIT_PURCHASES_ENABLED 2>/dev/null || echo "(not set)")
say "Web sales switch, EXPO_PUBLIC_CREDIT_PURCHASES_ENABLED: ${BOLD}${sales}${RESET}"
note "Both web apps read it. Anything but \"true\" hides Buy on the web."
pr=$(gh pr view "$BRANCH" --json number,state,url -q '"#\(.number) \(.state) \(.url)"' 2>/dev/null || echo "not found")
say "PR: $pr"
step "Open the PR's Checks tab and make sure every check is green."
step "Open the Activity page in another tab, to watch during and after: https://pinch-app.io/app/admin/activity"
pause "All green and ready? Press Enter."

# ──────────────────────────────────────────────────────────────────────────
stage "Supabase: sign-in return addresses"
say "Nothing should need changing: the new app returns to the same addresses as the Expo app"
say "(/app/auth-callback and /app/reset-password). This just confirms it."
open_url "$SUPABASE_URL_CONFIG"
step "Under Redirect URLs, look for https://pinch-app.io/app/** (or a wider pattern that covers it)."
step "If it's missing, click Add URL, paste https://pinch-app.io/app/** and save."
note "Google Cloud needs no change: Google sends people back to Supabase, not to pinch-app.io."
pause "Confirmed? Press Enter."

# ──────────────────────────────────────────────────────────────────────────
stage "Merge and deploy"
say "Merging deploys the new app's Worker with the routes pinch-app.io/app and /app/*."
say "From then on every visit to /app gets the new app. The Expo copy stays on GitHub Pages, unused,"
say "so switching back is quick."
if confirm "Merge the PR now?"; then
  since=$(date -u +%Y-%m-%dT%H:%M:%SZ)
  gh pr merge "$BRANCH" --squash --delete-branch
  say "Waiting for 'Deploy new web app' (about 5–10 minutes)…"
  if watch_run_since deploy-web-app.yml "$since"; then
    printf '  %s✓ Deployed, and its routing check passed.%s\n' "$GREEN" "$RESET"
  else
    warn "The deploy or its check failed. Open the run in the Actions tab."
    warn "If /app is broken, switch back now: docs/WEB-APP-SWITCH.md → Switching back."
    pause "Press Enter once you've dealt with it, or Ctrl-C to stop."
  fi
else
  note "Merge it yourself, wait for 'Deploy new web app' to finish, then come back."
  pause "Deployed? Press Enter."
fi

# ──────────────────────────────────────────────────────────────────────────
stage "Check every kind of address"
say "Old /app links on the new app; the landing page, guides, legal pages, /s/, /r/ and the"
say "app-link files where they were."
if check_routing next; then
  printf '  %s✓ Routing is right.%s\n' "$GREEN" "$RESET"
else
  warn "Something is wrong (listed above). If people can't use /app, switch back: docs/WEB-APP-SWITCH.md."
fi
pause "Press Enter to continue."

# ──────────────────────────────────────────────────────────────────────────
stage "Two browsers: new visitor and old session"
step "In a private window, open https://pinch-app.io/app. You should get the welcome page."
step "In your everyday browser, where you were signed in to the Expo web app, open https://pinch-app.io/app"
step "and press Ctrl+Shift+R. You should land in your Library, still signed in."
note "Without the hard refresh a browser may show the Expo app for up to 10 minutes (GitHub Pages' cache)."
note "You stay signed in because both apps keep the session under the same key on the same site."
pause "Both right? Press Enter."

# ──────────────────────────────────────────────────────────────────────────
stage "Sign in and import"
step "In the private window, sign in with Google. You should come back to pinch-app.io/app."
step "Snap a recipe link (any recipe website) and check it opens as a saved recipe."
step "Sign out from the account menu."
note "On the Activity page, the new app's events carry a version ending in \"-next\"."
pause "Done? Press Enter."

# ──────────────────────────────────────────────────────────────────────────
stage "A test purchase"
say "As for PIN-141: a \$0 purchase with a 100% discount code, or the smallest pack refunded afterwards."
step "Signed in on pinch-app.io/app, go to Settings → Credits and buy a pack."
step "After Polar's checkout you should be back on pinch-app.io/app/settings/credits, with"
step "\"payment received\" and the new balance."
open_url "https://polar.sh/dashboard"
step "If you paid, refund the order in Polar (the order's page has a Refund action)."
pause "Purchase worked? Press Enter."

# ──────────────────────────────────────────────────────────────────────────
stage "Practise switching back (1 of 2): to the Expo web app"
say "Removing the two routes hands /app back to GitHub Pages, where the Expo web app still is."
open_url "$CF_ROUTES_URL"
step "Pick your account if asked. You're on pinch-web → Settings → Domains & Routes."
step "Remove the route pinch-app.io/app/* and then the route pinch-app.io/app."
step "Leave next.pinch-app.io alone."
pause "Removed both? Press Enter to check."
if check_routing expo; then
  printf '  %s✓ /app is the Expo web app again. Switching back works.%s\n' "$GREEN" "$RESET"
else
  warn "/app isn't the Expo web app yet. Check both routes are gone, then run:"
  note "  node scripts/check-web-routing.mjs --expect expo"
fi
pause "Press Enter to switch forward again."

# ──────────────────────────────────────────────────────────────────────────
stage "Practise switching back (2 of 2): forward again"
say "Running the deploy again puts the routes back from web/wrangler.jsonc."
since=$(date -u +%Y-%m-%dT%H:%M:%SZ)
gh workflow run deploy-web-app.yml --ref master
say "Waiting for 'Deploy new web app' (about 5–10 minutes)…"
if watch_run_since deploy-web-app.yml "$since" && check_routing next; then
  printf '  %s✓ /app is the new web app again.%s\n' "$GREEN" "$RESET"
else
  warn "Not back yet. Look at the run in the Actions tab. The routes can also be added by hand on the"
  warn "page from the last stage: Add route → pinch-app.io/app and pinch-app.io/app/*, zone pinch-app.io."
fi
pause "Press Enter to continue."

# ──────────────────────────────────────────────────────────────────────────
stage "Tell people about the new look"
open_url "https://pinch-app.io/app/admin/messages"
step "Create a new message: a banner, platform web only, for everyone."
step "Suggested text: \"Pinch on the web has a new look. Everything you saved is right where you left it.\""
step "Fill in every language the form offers, and set it to end in two weeks."
pause "Published? Press Enter."

# ──────────────────────────────────────────────────────────────────────────
stage "Afterwards"
say "Over the next two weeks:"
step "Watch the Activity page for errors, and for people stuck at sign-in."
step "In 2–3 days, check Google Search Console → Pages for new errors on pinch-app.io."
step "Switching back stays possible until PIN-148 removes the Expo web app."
say ""
say "Then tell Claude \"switched, drill done on <date>\", so docs/WEB-APP-SWITCH.md and PIN-147 record it."
pause "Press Enter to finish."

finish
}

run_wizard "$@"; exit
